 27	public class Xzj27CommandService {
 28	
 29	    private final Xzj27Repository orderBidRepository;
 30	    private final Xdg64CommandService orderCommandService;
 31	    private final Xdh20QueryService productSizeQueryService;
 32	    private final Xrd81QueryService userQueryService;
