118	    @Transactional
119	    public Xzj27 createInstantOrderBid(String buyerEmail, Long saleBidId, Long addressId,
120	                                          boolean isWarehouseStorage, Xbf54RequestDto paymentRequest) {
121	        try {
122	
123	            validateInstantOrderBidInput(buyerEmail, saleBidId, addressId, paymentRequest);
124	
125	
126	            Xrd81 buyer = userQueryService.findByEmail(buyerEmail);
127	
128	
129	            Xzz58 saleBid = getSaleBidAndValidate(saleBidId);
130	            Xgg74 sale = saleBid.getSale();
131	
132	
133	            Xdg64 order = orderCommandService.createInstantOrder(
134	                    buyer,
135	                    saleBid,
136	                    addressId,
137	                    isWarehouseStorage,
138	                    paymentRequest
139	            );
140	
141	
142	            Xzj27 orderBid = createInstantOrderBid(order, saleBid, sale);
143	
144	            return orderBid;
145	        } catch (Exception e) {
146	            handleOrderBidCreationException(e, "즉시 구매 주문 입찰 생성");
147	            return null;
148	        }
149	    }
