   119	    )
   120	    @Transactional
   121	    public void handleOrderRetryEvent(
   122	            @Payload Xmr97Event event,
   123	            Acknowledgment acknowledgment) {
   125	        try {
   126	            log.info("주문 재시도 처리: 주문ID={}, 재시도횟수={}",
   127	                    event.getOrderId(), event.getRetryCount());
   129	            if (event.isMaxRetryExceeded()) {
   130	                log.error("최대 재시도 횟수 초과: 주문ID={}, 재시도횟수={}",
   131	                        event.getOrderId(), event.getRetryCount());
   134	                sendFailureNotification(event.getOrderId(), event.getUserEmail(), "최대 재시도 횟수 초과");
   135	                acknowledgment.acknowledge();
   136	                return;
   137	            }
   140	            if (isOrderAlreadyProcessed(event.getOrderId())) {
   141	                log.info("재시도 중 주문 완료 확인: 주문ID={}", event.getOrderId());
   142	                acknowledgment.acknowledge();
   143	                return;
   144	            }
   147	            Thread.sleep(Math.min(1000 * event.getRetryCount(), 5000));
   150	            handleOrderProcessingEvent(event, acknowledgment);
   152	        } catch (InterruptedException e) {
   153	            Thread.currentThread().interrupt();
   154	            log.error("주문 재시도 중 인터럽트 발생: 주문ID={}", event.getOrderId());
   155	            acknowledgment.acknowledge();
   156	        } catch (Exception e) {
   157	            log.error("주문 재시도 처리 중 오류: 주문ID={}, 오류={}",
   158	                    event.getOrderId(), e.getMessage(), e);
   159	            acknowledgment.acknowledge();
   160	        }
   161	    }
   166	    private void processCompleteOrder(Xdg64 order, Xrd81 user, Xrt49RequestDto requestDto) {
   167	        try {
   168	            log.info("전체 주문 처리 시작: 주문ID={}", order.getId());
   171	            Xbf54 payment = paymentCommandService.processPayment(order, user, requestDto.getPaymentRequest());
   172	            order.assignPayment(payment);
   174	            if (!payment.isSuccess()) {
   175	                throw new RuntimeException("결제 실패: " + payment.getStatus());
   176	            }
   178	            log.info("결제 처리 완료: 주문ID={}, 결제ID={}", order.getId(), payment.getId());
   181	            Xhx14 shipment = orderShipmentCommandService.createOrderShipment(
   182	                    order,
   183	                    requestDto.getReceiverName(),
   184	                    requestDto.getReceiverPhone(),
   185	                    requestDto.getPostalCode(),
   186	                    requestDto.getAddress()
   187	            );
   188	            order.assignOrderShipment(shipment);
   189	            log.info("배송 정보 생성 완료: 주문ID={}", order.getId());
   192	            if (!order.getStatus().canTransitionTo(Xdg64Status.PAYMENT_COMPLETED)) {
   193	                throw new RuntimeException("결제 완료 상태로 전환할 수 없습니다. 현재 상태: " + order.getStatus());
   194	            }
   195	            order.updateStatus(Xdg64Status.PAYMENT_COMPLETED);
   197	            if (requestDto.isWarehouseStorage()) {
   199	                Xnn94 warehouseStorage = warehouseStorageCommandService.createOrderStorage(order, user);
   200	                order.assignWarehouseStorage(warehouseStorage);
   203	                if (order.getStatus().canTransitionTo(Xdg64Status.PREPARING)) {
   204	                    order.updateStatus(Xdg64Status.PREPARING);
   205	                }
   206	                if (order.getStatus().canTransitionTo(Xdg64Status.IN_WAREHOUSE)) {
   207	                    order.updateStatus(Xdg64Status.IN_WAREHOUSE);
   208	                }
   209	                if (order.getStatus().canTransitionTo(Xdg64Status.COMPLETED)) {
   210	                    order.updateStatus(Xdg64Status.COMPLETED);
   211	                }
   213	                log.info("창고 보관 처리 완료: 주문ID={}", order.getId());
   214	            } else {
   216	                if (order.getStatus().canTransitionTo(Xdg64Status.PREPARING)) {
   217	                    order.updateStatus(Xdg64Status.PREPARING);
   218	                }
   219	                log.info("배송 준비 완료: 주문ID={}", order.getId());
   220	            }
   223	            orderRepository.save(order);
   224	            log.info("전체 주문 처리 완료: 주문ID={}, 최종상태={}", order.getId(), order.getStatus());
   226	        } catch (Exception e) {
   227	            log.error("전체 주문 처리 실패: 주문ID={}, 오류={}", order.getId(), e.getMessage(), e);
   228	            throw e;
   229	        }
   230	    }
   235	    private boolean isOrderAlreadyProcessed(Long orderId) {
   236	        try {
   237	            Xdg64 order = orderRepository.findById(orderId).orElse(null);
   238	            if (order == null) {
   239	                return false;
   240	            }
   243	            Xdg64Status currentStatus = order.getStatus();
   244	            return currentStatus != Xdg64Status.PENDING_PAYMENT;
   246	        } catch (Exception e) {
   247	            log.error("주문 중복 검사 중 오류 발생: 주문ID={}, 오류={}", orderId, e.getMessage(), e);
   248	            return false;
   249	        }
   250	    }
   255	    private void handleOrderProcessingFailure(Xmr97Event event, Exception error, Acknowledgment acknowledgment) {
   256	        try {
   258	            if (isRetryableError(error)) {
   259	                log.info("재시도 가능한 오류로 재시도 이벤트 발행: 주문ID={}", event.getOrderId());
   260	                orderEventProducer.sendOrderRetryEvent(event);
   261	            } else {
   262	                log.error("재시도 불가능한 오류로 주문 처리 실패: 주문ID={}, 오류={}",
   263	                        event.getOrderId(), error.getMessage());
   264	                sendFailureNotification(event.getOrderId(), event.getUserEmail(), error.getMessage());
   265	            }
   267	            acknowledgment.acknowledge();
   269	        } catch (Exception e) {
   270	            log.error("주문 처리 실패 처리 중 오류: 주문ID={}, 오류={}", event.getOrderId(), e.getMessage(), e);
   271	            acknowledgment.acknowledge();
   272	        }
   273	    }
   278	    private boolean isRetryableError(Exception error) {
   280	        return !(error instanceof IllegalArgumentException) &&
   281	                !(error.getMessage() != null && error.getMessage().contains("찾을 수 없습니다"));
   282	    }
   287	    private void sendSuccessNotification(Long orderId, String userEmail) {
   288	        try {
   289	            Map<String, Object> notification = new HashMap<>();
   290	            notification.put("orderId", orderId);
   291	            notification.put("userEmail", userEmail);
   292	            notification.put("status", "SUCCESS");
   293	            notification.put("type", "ORDER_COMPLETED");
   294	            notification.put("title", "주문 완료");
   295	            notification.put("message", "주문 및 결제가 성공적으로 완료되었습니다!");
   296	            notification.put("timestamp", LocalDateTime.now());
   299	            String userDestination = "/user/" + userEmail + "/queue/notifications";
   300	            messagingTemplate.convertAndSendToUser(userEmail, "/queue/notifications", notification);
   303	            String orderDestination = "/topic/order/" + orderId;
   304	            messagingTemplate.convertAndSend(orderDestination, notification);
   306	            log.info("주문 성공 WebSocket 알림 전송 완료: 주문ID={}, 사용자={}, 대상={}",
   307	                    orderId, userEmail, userDestination);
   310	            try {
   311	                Map<String, Object> kafkaNotification = new HashMap<>();
   312	                kafkaNotification.put("type", "ORDER_COMPLETION");
   313	                kafkaNotification.put("orderId", orderId);
   314	                kafkaNotification.put("userEmail", userEmail);
   315	                kafkaNotification.put("message", "주문이 완료되었습니다");
   316	                kafkaNotification.put("timestamp", System.currentTimeMillis());
   318	                notificationKafkaTemplate.send("notification-topic", userEmail, kafkaNotification);
   319	                log.debug("주문 완료 Kafka 알림 이벤트 발행: 주문ID={}", orderId);
   321	            } catch (Exception kafkaError) {
   322	                log.warn("Kafka 알림 이벤트 발행 실패 (WebSocket 알림은 성공): 주문ID={}, 오류={}",
   323	                        orderId, kafkaError.getMessage());
   324	            }
   326	        } catch (Exception e) {
   327	            log.error("성공 알림 전송 실패: 주문ID={}, 오류={}", orderId, e.getMessage(), e);
   328	        }
   329	    }
   334	    private void sendFailureNotification(Long orderId, String userEmail, String errorMessage) {
